import { expect, test, uniqueName } from "../../fixtures";

// Scenario: Review vendors / Insurance expiring within 30 days is flagged.
//
// Assumption: the insurance certificate's expiry date is extracted from the uploaded
// document's text, in ISO form ("Expiration Date: YYYY-MM-DD"). The buffer below is
// built to carry that line so the extraction pipeline can read the expiry date.

const DAY_MS = 24 * 60 * 60 * 1000;
const FLAG = "insurance_expiring_soon";

/** ISO date (YYYY-MM-DD, UTC) that is `days` days from today. */
function expiryDateIn(days: number): string {
  const today = new Date();
  const todayUtc = Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate());
  return new Date(todayUtc + days * DAY_MS).toISOString().slice(0, 10);
}

const examples = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
] as const;

test.describe("insurance expiry flag", () => {
  for (const { days, include } of examples) {
    const verb = include ? "include" : "do not include";

    test(
      `insurance expiring in ${days} days: vendor flags ${verb} "${FLAG}"`,
      { tag: "@REV-08" },
      async ({ apiAs }) => {
        // Arrange: a member creates a vendor and uploads an insurance certificate
        // whose expiry date is `days` days from today.
        const member = await apiAs("member");

        const created = await member.post("/api/vendors", {
          data: {
            name: uniqueName(`Expiry ${days}d`),
            category: "services",
            contact_email: `expiry-${days}-${Date.now().toString(36)}@example.test`,
          },
        });
        expect(created.status()).toBe(201);
        const vendor = await created.json();

        const certificate = Buffer.from(
          [
            "CERTIFICATE OF INSURANCE",
            `Expiration Date: ${expiryDateIn(days)}`,
          ].join("\n"),
        );
        const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: "insurance_certificate",
            file: {
              name: "insurance.txt",
              mimeType: "text/plain",
              buffer: certificate,
            },
          },
        });
        expect(upload.status()).toBe(201);
        const document = await upload.json();

        // Wait for extraction to finish before reading the vendor's flags.
        await expect
          .poll(
            async () => {
              const response = await member.get(`/api/documents/${document.id}`);
              expect(response.status()).toBe(200);
              return (await response.json()).status;
            },
            { timeout: 60_000, intervals: [500, 1000, 2000] },
          )
          .toBe("extracted");

        // Act: request the vendor.
        const response = await member.get(`/api/vendors/${vendor.id}`);

        // Assert: the flag is present or absent per the scenario.
        expect(response.status()).toBe(200);
        const body = await response.json();
        if (include) {
          expect(body.flags).toContain(FLAG);
        } else {
          expect(body.flags).not.toContain(FLAG);
        }
      },
    );
  }
});
